return {
  apply(ctx) {
    const readStatus = async () => {
      // 注意: 部分 DSH 版本 fs.resolve 不展开 '~', 若读到 null 请改为绝对路径如 C:/Users/<你>/\.dsh/downloads/active.json
      const abs = '~/.dsh/downloads/active.json'
      const fs = ctx.get('fs')
      if (!fs) return null
      try {
        const target = await fs.resolve(abs)
        const info = await fs.stat(target)
        if (!info) return null
        const text = await fs.readText(target)
        try { return JSON.parse(text) } catch (e) { return null }
      } catch (e) { return null }
    }
    const disposer = harness.handle('dl-status', async () => await readStatus())
    ctx.effect(() => disposer)
  },
}

