return {
  inject: ['timer'],
  apply(ctx) {
    const slots = ctx.get('slots')
    if (slots === undefined) return
    slots.inject('shell.overlay', () => slots.register(
      { name: 'shell.overlay', id: 'dl-progress-overlay', order: 50 },
      () => {
        const [state, setState] = React.useState(null)
        const [err, setErr] = React.useState('')
        React.useEffect(() => {
          const tick = () => {
            host.call('dl-status').then((data) => {
              setState(data)
              setErr('')
            }).catch((e) => setErr(String(e && e.message ? e.message : e)))
          }
          tick()
          const disposer = ctx.interval(tick, 1000)
          return disposer
        }, [])
        const outer = {
          position: 'fixed', right: 20, bottom: 140, zIndex: 9999,
          width: 300, background: '#1c1c1e', border: '1px solid #333',
          borderRadius: 10, padding: '12px 14px', boxShadow: '0 4px 20px rgba(0,0,0,.5)',
          fontFamily: 'system-ui', color: '#eee',
        }
        if (err) {
          return React.createElement('div', { style: outer },
            React.createElement('div', { style: { fontSize: 13, fontWeight: 600, color: '#e5484d' } }, '⬇ 下载进度条错误'),
            React.createElement('div', { style: { fontSize: 12, color: '#999', marginTop: 4, wordBreak: 'break-all' } }, err),
          )
        }
        if (!state) {
          return React.createElement('div', { style: outer },
            React.createElement('div', { style: { fontSize: 13, fontWeight: 600 } }, '⬇ 下载进度条待命'),
            React.createElement('div', { style: { fontSize: 12, color: '#999', marginTop: 4 } }, '等待下载任务…(每秒轮询中)'),
          )
        }
        if (state.status === 'done') {
          return React.createElement('div', { style: outer },
            React.createElement('div', { style: { fontSize: 13, fontWeight: 600, color: '#46a758' } }, '✅ 下载完成'),
            React.createElement('div', { style: { fontSize: 12, color: '#999', marginTop: 4, wordBreak: 'break-all' } }, state.name || ''),
          )
        }
        const pct = Math.min(100, Math.max(0, state.percent || 0))
        const speed = state.speedMBps ? state.speedMBps.toFixed(1) : '0'
        const doneMB = state.downloaded ? (state.downloaded / 1048576).toFixed(1) : '0'
        const totalMB = state.total ? (state.total / 1048576).toFixed(1) : '?'
        const eta = state.etaSec != null && state.etaSec > 0 ? Math.round(state.etaSec) + 's' : '—'
        const bar = { height: 8, borderRadius: 4, background: '#2a2a2a', overflow: 'hidden', width: '100%', marginTop: 6 }
        const fill = { height: '100%', width: pct + '%', background: '#4c9aff', transition: 'width 0.5s ease' }
        return React.createElement('div', { style: outer },
          React.createElement('div', { style: { display: 'flex', justifyContent: 'space-between', fontSize: 13, fontWeight: 600 } },
            React.createElement('span', null, '⬇ ' + (state.name || '下载')),
            React.createElement('span', { style: { color: '#999' } }, pct + '%'),
          ),
          React.createElement('div', { style: bar }, React.createElement('div', { style: fill })),
          React.createElement('div', { style: { display: 'flex', justifyContent: 'space-between', fontSize: 12, color: '#999', marginTop: 5 } },
            React.createElement('span', null, doneMB + ' / ' + totalMB + ' MB · ' + speed + ' MB/s'),
            React.createElement('span', null, '剩余 ' + eta),
          ),
        )
      },
    ))
  },
}
